-- Do not edit: change the spec in model/ and regenerate.

CREATE OR REPLACE VIEW lr_serverless_aws_us_catalog.bricksurance_reserving.reserving_metrics
COMMENT 'Certified reserving KPIs over the loss-development triangle - cumulative paid and incurred by accident year, line of business and development lag - defined once so the reserving actuary, the finance close and Genie all read the same figures. Ultimate, IBNR and the chain-ladder / Bornhuetter-Ferguson projections are computed in the reserving notebook from these same movements and published to finance.valuation_result. Amounts are in original currency: always group by or filter on currency_code before summing. Query measures with MEASURE(name).'
WITH METRICS
LANGUAGE YAML
AS $$
version: 0.1

source: lr_serverless_aws_us_catalog.bricksurance_reserving.loss_development

joins:
  - name: line_of_business
    source: lr_serverless_aws_us_catalog.bricksurance_reference.line_of_business
    on: source.line_of_business_code = line_of_business.line_of_business_code

dimensions:
  - name: accident_year
    expr: accident_year
  - name: development_lag
    expr: development_lag
  - name: line_of_business
    expr: line_of_business.label
  - name: line_of_business_code
    expr: source.line_of_business_code
  - name: currency_code
    expr: currency_code

measures:
  - name: paid_to_date
    expr: SUM(incremental_paid)
  - name: incurred_to_date
    expr: SUM(incremental_incurred)
  - name: paid_ratio
    expr: SUM(incremental_paid) / NULLIF(SUM(incremental_incurred), 0)
  - name: accident_year_count
    expr: COUNT(DISTINCT accident_year)
$$;
